package com.flipledger;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Sorts GE items into consumable groups by name. Anything that doesn't match isn't suggested.
 */
final class Consumables
{
	enum Group
	{
		POTIONS, FOOD, RUNES, AMMO, HERBS, SEEDS, BONES, TELEPORTS, SUPPLIES
	}

	private static final Set<String> FOOD = set(
		"shark", "manta ray", "anglerfish", "dark crab", "sea turtle", "tuna potato", "lobster", "swordfish",
		"monkfish", "cooked karambwan", "pineapple pizza", "anchovy pizza", "meat pizza", "plain pizza", "cake",
		"chocolate cake", "trout", "salmon", "tuna", "bass", "pike", "shrimps", "anchovies", "sardine", "herring",
		"mackerel", "cod", "cooked chicken", "cooked meat", "bread", "potato with cheese", "egg potato",
		"mushroom potato", "chilli potato", "curry", "stew", "jug of wine", "beer", "banana", "pineapple",
		"watermelon", "strawberry", "papaya fruit", "coconut", "purple sweets", "saradomin brew(4)",
		"blighted manta ray", "blighted anglerfish", "blighted karambwan", "cooked sunlight antelope",
		"cooked dashing kebbit", "cooked moonlight antelope", "botanical pie", "summer pie", "wild pie",
		"admiral pie", "mushroom pie", "dragonfruit", "dragonfruit pie", "cooked bream", "cooked moss lizard",
		"cooked rainbow fish", "cave eel", "slimy eel", "lava eel", "giant carp");

	private static final Set<String> HERBS = set(
		"guam leaf", "marrentill", "tarromin", "harralander", "ranarr weed", "toadflax", "irit leaf", "avantoe",
		"kwuarm", "huasca", "snapdragon", "cadantine", "lantadyme", "dwarf weed", "torstol",
		"eye of newt", "limpwurt root", "red spiders' eggs", "white berries", "snape grass", "wine of zamorak",
		"unicorn horn dust", "chocolate dust", "crushed nest", "potato cactus", "zulrah's scales",
		"dragon scale dust", "crystal dust", "mort myre fungus", "jangerberries", "goat horn dust", "lava scale shard",
		"amylase crystal", "nail beast nails", "ground mud runes", "magic roots", "yew roots", "ancient brew",
		"ground desert goat horn", "araxyte venom sack", "vial of water", "vial", "grapes", "cactus spine",
		"ashes", "volcanic ash");

	private static final Set<String> SUPPLIES = set(
		"pure essence", "rune essence", "daeyalt essence", "ancient essence", "revenant ether", "sunfire splinters",
		"blighted ancient ice sack", "blighted entangle sack", "blighted teleport spell sack", "blighted bind sack",
		"blighted snare sack", "blighted vengeance sack", "coconut", "compost", "supercompost", "ultracompost",
		"bucket of sand", "soda ash", "seaweed", "giant seaweed", "molten glass", "feather", "steel nails",
		"mithril nails", "adamantite nails", "bow string", "flax", "battlestaff", "air orb", "water orb", "earth orb",
		"fire orb", "unpowered orb", "plank", "oak plank", "teak plank", "mahogany plank", "camphor plank",
		"ironwood plank", "rosewood plank", "gold bar", "silver bar", "bronze bar", "iron bar", "steel bar",
		"mithril bar", "adamantite bar", "runite bar", "coal", "iron ore", "gold ore", "silver ore", "mithril ore",
		"adamantite ore", "runite ore", "logs", "oak logs", "willow logs", "maple logs", "yew logs", "magic logs",
		"redwood logs", "teak logs", "mahogany logs", "dragon bones", "green dragonhide", "blue dragonhide",
		"red dragonhide", "black dragonhide", "green dragon leather", "blue dragon leather", "red dragon leather",
		"black dragon leather", "cannonball", "steel cannonball", "granite cannonball", "frozen tear",
		"dark essence block", "cosmic rune");

	private Consumables()
	{
	}

	private static Set<String> set(String... s)
	{
		return new HashSet<>(Arrays.asList(s));
	}

	static Group groupOf(String rawName)
	{
		String n = rawName.toLowerCase(Locale.ROOT).trim();

		if (n.endsWith(" rune") && !n.contains("pouch"))
		{
			return Group.RUNES;
		}
		if (n.matches(".*\\([1-4]\\)$") || n.endsWith("(unf)") || n.contains("potion") || n.contains(" brew")
			|| n.startsWith("anti") || n.contains("antifire") || n.contains("antivenom") || n.contains("antidote")
			|| n.contains("stamina") || n.contains("restore") || n.contains("divine ") || n.contains(" mix("))
		{
			return n.endsWith("(unf)") ? Group.HERBS : Group.POTIONS;
		}
		if (n.endsWith(" bones") || n.equals("bones") || n.endsWith(" ashes") || n.endsWith(" remains"))
		{
			return Group.BONES;
		}
		if (n.endsWith(" seed") || n.endsWith(" sapling") || n.endsWith(" spore"))
		{
			return Group.SEEDS;
		}
		if (n.endsWith(" teleport") || n.endsWith("(tablet)") || n.endsWith("teleport scroll") || n.startsWith("teleport to"))
		{
			return Group.TELEPORTS;
		}
		if (n.endsWith(" arrow") || n.endsWith(" arrows") || n.contains(" arrow(") || n.contains(" bolts")
			|| n.endsWith(" dart") || n.contains(" dart(") || n.endsWith(" javelin") || n.contains(" javelin(")
			|| n.endsWith("cannonball") || n.contains("chinchompa") || n.endsWith(" knife") && n.contains("throwing")
			|| n.endsWith(" thrownaxe") || n.endsWith(" dart tip") || n.endsWith(" javelin heads") || n.endsWith(" arrowtips"))
		{
			return Group.AMMO;
		}
		if (n.startsWith("grimy ") || HERBS.contains(n))
		{
			return Group.HERBS;
		}
		if (FOOD.contains(n) || n.startsWith("cooked "))
		{
			return Group.FOOD;
		}
		if (SUPPLIES.contains(n))
		{
			return Group.SUPPLIES;
		}
		return null;
	}

	static boolean enabled(Group g, FlipLedgerConfig c)
	{
		switch (g)
		{
			case POTIONS:
				return c.catPotions();
			case FOOD:
				return c.catFood();
			case RUNES:
				return c.catRunes();
			case AMMO:
				return c.catAmmo();
			case HERBS:
				return c.catHerbs();
			case SEEDS:
				return c.catSeeds();
			case BONES:
				return c.catBones();
			case TELEPORTS:
				return c.catTeleports();
			default:
				return c.catSupplies();
		}
	}
}

package com.flipledger;

import com.google.gson.Gson;
import java.io.IOException;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Opt-in: sends only this player's own 1h / 12h / 24h profit and flip count to the crew's
 * leaderboard Worker. Off by default; nothing is sent without a URL and group key.
 */
class CrewLeaderboard
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(CrewLeaderboard.class);
	static final ZoneId EASTERN = ZoneId.of("America/New_York");
	static final int[] WINDOW_HOURS = {1, 12, 24};
	private static final String[] WINDOW_KEYS = {"h1", "h12", "h24"};
	private static final long MIN_GAP_MS = 60_000;
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private final OkHttpClient http;
	private final Gson gson;
	private volatile long lastSent;
	private volatile boolean pending;
	volatile String lastStatus = "Not sent yet";

	CrewLeaderboard(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	/** Start (unix seconds) of the Eastern-time window containing nowSec. Same rule as the Worker. */
	static long windowStart(int hours, long nowSec)
	{
		ZonedDateTime z = Instant.ofEpochSecond(nowSec).atZone(EASTERN);
		long elapsed = (z.getHour() % hours) * 3600L + z.getMinute() * 60L + z.getSecond();
		return nowSec - elapsed;
	}

	void markDirty()
	{
		pending = true;
	}

	/** Call periodically and after sales. Sends at most once a minute, only when something changed. */
	void maybeSend(FlipLedgerConfig cfg, String playerName, List<LedgerData.Event> events, String token, Consumer<String> saveToken)
	{
		if (!pending || !cfg.crewEnabled() || events == null)
		{
			return;
		}
		String url = cfg.crewUrl().trim();
		String key = cfg.crewKey().trim();
		// Always the logged-in RuneScape name; it can't be typed in
		String name = playerName == null ? null : playerName.replace('\u00A0', ' ').trim();
		if (url.isEmpty() || key.isEmpty() || name == null || name.isEmpty())
		{
			lastStatus = "Needs a submit URL and crew key (and to be logged in)";
			return;
		}
		if (System.currentTimeMillis() - lastSent < MIN_GAP_MS)
		{
			return;
		}
		HttpUrl base = HttpUrl.parse(url);
		if (base == null || !"https".equals(base.scheme()))
		{
			lastStatus = "Submit URL must start with https://";
			return;
		}
		HttpUrl submit = base.newBuilder().encodedPath("/submit").build();

		long now = System.currentTimeMillis() / 1000;
		Map<String, Object> windows = new LinkedHashMap<>();
		for (int i = 0; i < WINDOW_HOURS.length; i++)
		{
			long start = windowStart(WINDOW_HOURS[i], now);
			long profit = 0;
			int flips = 0;
			LedgerData.Event best = null;
			for (LedgerData.Event e : events)
			{
				if (e.t >= start)
				{
					profit += e.profit;
					flips += e.flips;
					if (e.flips > 0 && e.item != null && (best == null || e.flipTotal > best.flipTotal))
					{
						best = e;
					}
				}
			}
			Map<String, Object> w = new LinkedHashMap<>();
			w.put("start", start);
			w.put("profit", profit);
			w.put("flips", flips);
			if (best != null)
			{
				w.put("best", best.flipTotal);
				w.put("bestItem", best.item);
			}
			windows.put(WINDOW_KEYS[i], w);
		}
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("name", name);
		body.put("windows", windows);

		pending = false;
		lastSent = System.currentTimeMillis();
		Request.Builder rb = new Request.Builder().url(submit).header("X-Group-Key", key);
		if (token != null && !token.isEmpty())
		{
			rb.header("X-Player-Token", token);
		}
		Request req = rb
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				pending = true;
				lastStatus = "Couldn't reach the leaderboard";
				log.debug("Flip Ledger: leaderboard submit failed", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					// body read below
					String text = r.body() != null ? r.body().string() : "";
					if (r.code() == 403)
					{
						lastStatus = text.contains("claimed")
							? "Your name is claimed on another device; ask your crew leader to free it"
							: "Crew key was rejected";
					}
					else if (!r.isSuccessful())
					{
						pending = true;
						lastStatus = "Leaderboard error " + r.code();
					}
					else
					{
						com.google.gson.JsonObject o = gson.fromJson(text, com.google.gson.JsonObject.class);
						if (o != null && o.has("token") && !o.get("token").isJsonNull())
						{
							saveToken.accept(o.get("token").getAsString());
						}
						lastStatus = "Sent " + java.time.LocalTime.now().withNano(0);
					}
				}
			}
		});
	}
}

package com.flipledger;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(FlipLedgerConfig.GROUP)
public interface FlipLedgerConfig extends Config
{
	String GROUP = "flipledger";

	@ConfigSection(name = "Flipping session", description = "How suggestions are picked and sized", position = 0)
	String session = "session";

	@ConfigSection(name = "Item types", description = "Which consumables to suggest", position = 1)
	String types = "types";

	@ConfigSection(name = "Display", description = "Floating text and chat", position = 2)
	String display = "display";

	@ConfigSection(name = "Crew leaderboard", description = "Optional: share your own profit with your group's leaderboard", position = 3)
	String crew = "crew";

	@ConfigItem(keyName = "crewEnabled", name = "Share with crew leaderboard",
		description = "Off by default. Sends only your name, profit and flip count for the current 1h / 12h / 24h windows to the URL below",
		warning = "This sends your RuneScape name, your flipping profit and flip counts to the third-party server "
			+ "you enter below (your crew's leaderboard), which is not controlled or verified by RuneLite developers. "
			+ "It also reveals your IP address to that server. Only turn this on for a server you trust.",
		section = crew, position = 1)
	default boolean crewEnabled()
	{
		return false;
	}

	@ConfigItem(keyName = "crewUrl", name = "Submit URL", description = "Your crew's leaderboard address, e.g. https://flips.yourname.workers.dev",
		section = crew, position = 3)
	default String crewUrl()
	{
		return "";
	}

	@ConfigItem(keyName = "crewKey", name = "Crew key", description = "The crew key from your crew leader. Your RuneScape name is claimed for you on your first submit", secret = true,
		section = crew, position = 4)
	default String crewKey()
	{
		return "";
	}

	// ---------- session ----------

	@ConfigItem(keyName = "budget", name = "GP to use", description = "Total gp for suggested flips, e.g. 50m or 750k",
		section = session, position = 1)
	default String budget()
	{
		return "50m";
	}

	@ConfigItem(keyName = "maxPerSlot", name = "Max per slot", description = "Most gp in any single suggestion, e.g. 10m",
		section = session, position = 2)
	default String maxPerSlot()
	{
		return "10m";
	}

	@ConfigItem(keyName = "minProfit", name = "Min profit", description = "Hide suggestions that make less than this, e.g. 25k",
		section = session, position = 3)
	default String minProfit()
	{
		return "25k";
	}

	@ConfigItem(keyName = "fillWindow", name = "Fill window", description = "How long you're willing to wait for an offer to fill",
		section = session, position = 4)
	default FillWindow fillWindow()
	{
		return FillWindow.MIN_30;
	}

	@ConfigItem(keyName = "showRisky", name = "Show risky items", description = "Also suggest items that are sliding or spiking (not recommended)",
		section = session, position = 5)
	default boolean showRisky()
	{
		return false;
	}

	@ConfigItem(keyName = "blockedItems", name = "Blocked items", description = "Item IDs you blocked from suggestions",
		hidden = true, section = session, position = 7)
	default String blockedItems()
	{
		return "";
	}

	@ConfigItem(keyName = "suggestions", name = "Suggestions", description = "Download public OSRS Wiki prices to suggest flips (about 10 small requests an hour, only while logged in)",
		section = session, position = 6)
	default boolean suggestions()
	{
		return true;
	}

	// ---------- item types ----------

	@ConfigItem(keyName = "catPotions", name = "Potions", description = "", section = types, position = 1)
	default boolean catPotions()
	{
		return true;
	}

	@ConfigItem(keyName = "catFood", name = "Food", description = "", section = types, position = 2)
	default boolean catFood()
	{
		return true;
	}

	@ConfigItem(keyName = "catRunes", name = "Runes", description = "", section = types, position = 3)
	default boolean catRunes()
	{
		return true;
	}

	@ConfigItem(keyName = "catAmmo", name = "Ammo", description = "Arrows, bolts, darts, javelins, cannonballs, chinchompas", section = types, position = 4)
	default boolean catAmmo()
	{
		return true;
	}

	@ConfigItem(keyName = "catHerbs", name = "Herbs & secondaries", description = "", section = types, position = 5)
	default boolean catHerbs()
	{
		return true;
	}

	@ConfigItem(keyName = "catSeeds", name = "Seeds & saplings", description = "", section = types, position = 6)
	default boolean catSeeds()
	{
		return true;
	}

	@ConfigItem(keyName = "catBones", name = "Bones & ashes", description = "", section = types, position = 7)
	default boolean catBones()
	{
		return true;
	}

	@ConfigItem(keyName = "catTeleports", name = "Teleports", description = "Tablets and scrolls", section = types, position = 8)
	default boolean catTeleports()
	{
		return true;
	}

	@ConfigItem(keyName = "catSupplies", name = "Other supplies", description = "Essence, ether, splinters, ice sacks, coconuts and similar", section = types, position = 9)
	default boolean catSupplies()
	{
		return true;
	}

	// ---------- display ----------

	@ConfigItem(keyName = "showFloatingText", name = "Floating text on player",
		description = "Green +gp / red -gp above your character when a sale completes", section = display, position = 1)
	default boolean showFloatingText()
	{
		return true;
	}

	@Range(min = 1, max = 10)
	@ConfigItem(keyName = "floatingSeconds", name = "Floating text seconds", description = "How long the text stays on screen",
		section = display, position = 2)
	default int floatingSeconds()
	{
		return 3;
	}

	@Range(min = 10, max = 32)
	@ConfigItem(keyName = "floatingFontSize", name = "Floating text size", description = "Font size of the text above your character",
		section = display, position = 3)
	default int floatingFontSize()
	{
		return 18;
	}

	@ConfigItem(keyName = "showOnGeSlots", name = "Floating text on GE offers",
		description = "Float profit (sales) and quantity (buys) over the offer slot each time it fills", section = display, position = 4)
	default boolean showOnGeSlots()
	{
		return true;
	}

	@ConfigItem(keyName = "showPriceCheck", name = "Price check while making offers",
		description = "Show recommended prices for the item you pick when setting up a GE offer", section = display, position = 0)
	default boolean showPriceCheck()
	{
		return true;
	}

	@ConfigItem(keyName = "crashAlerts", name = "Price drop alerts",
		description = "Warn in chat and with a notification when something you hold or are selling drops below break-even or falls 3%+ fast",
		section = display, position = 0)
	default boolean crashAlerts()
	{
		return true;
	}

	@ConfigItem(keyName = "showChatMessage", name = "Chat message", description = "Post a line in your chat box (only you see it) for each sale",
		section = display, position = 5)
	default boolean showChatMessage()
	{
		return true;
	}

	@ConfigItem(keyName = "applyTax", name = "Subtract 2% GE tax",
		description = "Subtract the GE tax from sale proceeds (2%, nothing under 50 gp, capped at 5M per item)", section = display, position = 6)
	default boolean applyTax()
	{
		return true;
	}

	enum FillWindow
	{
		MIN_5("5 min", 5),
		MIN_15("15 min", 15),
		MIN_30("30 min", 30),
		HOUR_1("1 hour", 60),
		HOUR_4("4 hours", 240);

		final String label;
		final int minutes;

		FillWindow(String label, int minutes)
		{
			this.label = label;
			this.minutes = minutes;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}
}

package com.flipledger;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.List;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

/**
 * Sidebar with four tabs: Settings, Info, Session and Offers.
 */
class FlipLedgerPanel extends PluginPanel
{
	private final SettingsTab settings;
	private final SessionTab session;

	FlipLedgerPanel(ConfigManager configManager, FlipLedgerConfig config,
		Runnable onSettingsChanged, Runnable onReset, Runnable onClear, Runnable onRefreshSuggestions,
		java.util.function.IntConsumer onBlock)
	{
		super(false);
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		settings = new SettingsTab(configManager, config, onSettingsChanged);
		InfoTab info = new InfoTab();
		session = new SessionTab(onReset, onClear, onRefreshSuggestions, onBlock);

		JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARK_GRAY_COLOR);
		MaterialTabGroup tabs = new MaterialTabGroup(display);
		tabs.setBorder(new EmptyBorder(8, 0, 4, 0));

		MaterialTab settingsTab = new MaterialTab("Settings", tabs, scroll(settings));
		MaterialTab infoTab = new MaterialTab("Info", tabs, scroll(info));
		MaterialTab sessionTab = new MaterialTab("Session", tabs, scroll(session));
		MaterialTab offersTab = new MaterialTab("Offers", tabs, scroll(session.offersView()));
		tabs.addTab(settingsTab);
		tabs.addTab(infoTab);
		tabs.addTab(sessionTab);
		tabs.addTab(offersTab);
		// Four tabs don't fit the sidebar in a flow layout; use four equal columns instead
		tabs.removeAll();
		tabs.setLayout(new java.awt.GridBagLayout());
		java.awt.GridBagConstraints gc = new java.awt.GridBagConstraints();
		gc.weightx = 1;
		gc.fill = java.awt.GridBagConstraints.HORIZONTAL;
		for (MaterialTab t : new MaterialTab[]{settingsTab, infoTab, sessionTab, offersTab})
		{
			t.setHorizontalAlignment(javax.swing.SwingConstants.CENTER);
			t.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
			tabs.add(t, gc);
		}
		tabs.select(sessionTab);

		add(tabs, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);
	}

	private static JScrollPane scroll(JPanel content)
	{
		WidthPanel wrap = new WidthPanel(new BorderLayout());
		wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrap.setBorder(new EmptyBorder(6, 10, 10, 10));
		wrap.add(content, BorderLayout.NORTH);
		JScrollPane sp = new JScrollPane(wrap);
		sp.setBorder(null);
		sp.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		sp.getVerticalScrollBar().setUnitIncrement(16);
		sp.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return sp;
	}

	void update(long profit, int flips, long sessionMs, LedgerData data)
	{
		session.update(profit, flips, sessionMs, data);
	}

	void updateOffers(List<OfferView> views)
	{
		session.updateOffers(views);
	}

	void updateSuggestions(List<Suggester.Suggestion> list, String status)
	{
		session.updateSuggestions(list, status);
	}

	void reloadSettings()
	{
		settings.reload();
	}
}

package com.flipledger;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
