package com.flipledger;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Everything saved per RuneScape account (stored in RuneLite's profile config).
 */
class LedgerData
{
	static final int MAX_HISTORY = 300;

	/** Items bought through the GE that haven't been sold yet: itemId -> cost basis. */
	Map<Integer, Position> positions = new HashMap<>();

	/** Last seen state of each GE slot, so progress is only counted once. */
	SlotSnapshot[] slots = new SlotSnapshot[8];

	long allTimeProfit;
	int allTimeFlips;

	/** Profit and completed-flip events from the last ~26 hours, for the crew leaderboard. */
	List<Event> events = new ArrayList<>();

	synchronized List<Event> eventsCopy()
	{
		return new ArrayList<>(events);
	}

	synchronized void addEvent(long profit, int flips, long flipTotal, String item)
	{
		long now = System.currentTimeMillis() / 1000;
		Event ev = new Event(now, profit, flips);
		if (flips > 0)
		{
			ev.flipTotal = flipTotal;
			ev.item = item;
		}
		events.add(ev);
		events.removeIf(e -> e.t < now - 26 * 3600);
	}

	static class Event
	{
		long t;
		long profit;
		int flips;
		/** Set when a flip finished: its whole profit and the item, for "best single flip". */
		long flipTotal;
		String item;

		Event(long t, long profit, int flips)
		{
			this.t = t;
			this.profit = profit;
			this.flips = flips;
		}
	}

	/** GE buy limits: units bought per item in its current 4-hour window. */
	static final long LIMIT_WINDOW_MS = 4L * 3600 * 1000;
	Map<Integer, LimitWindow> limits = new HashMap<>();

	static class LimitWindow
	{
		/** When the first buy of this window filled; the limit resets 4 hours after this. */
		long start;
		long bought;
		String name;
		int limit;
	}

	/** Count units that just filled on a buy offer. The window starts with the first buy after the last reset. */
	synchronized void addBought(int itemId, long qty, long now, String name, int limit)
	{
		if (limits == null)
		{
			limits = new HashMap<>();
		}
		limits.values().removeIf(w -> now >= w.start + LIMIT_WINDOW_MS);
		LimitWindow w = limits.get(itemId);
		if (w == null)
		{
			w = new LimitWindow();
			w.start = now;
			limits.put(itemId, w);
		}
		w.bought += qty;
		w.name = name;
		if (limit > 0)
		{
			w.limit = limit;
		}
	}

	/** The item's current window, or null if nothing was bought in the last 4 hours. */
	synchronized LimitWindow limitWindow(int itemId, long now)
	{
		LimitWindow w = limits == null ? null : limits.get(itemId);
		return w == null || now >= w.start + LIMIT_WINDOW_MS ? null : w;
	}

	/** Active windows, soonest reset first. */
	synchronized List<LimitWindow> activeLimits(long now)
	{
		List<LimitWindow> out = new ArrayList<>();
		if (limits != null)
		{
			for (LimitWindow w : limits.values())
			{
				if (now < w.start + LIMIT_WINDOW_MS)
				{
					out.add(w);
				}
			}
		}
		out.sort((a, b) -> Long.compare(a.start, b.start));
		return out;
	}

	/**
	 * You made something: move what the inputs cost onto the output, so selling it shows the real profit.
	 * Inputs you bought through the GE carry their actual cost; any other input (mined, picked up, bought
	 * before the plugin) is counted at today's price, {@code marketEach}.
	 */
	synchronized void transferMade(int outId, long outQty, String outName, int[] inputs, long[] used, long[] marketEach,
		long now)
	{
		long total = 0;
		for (int i = 0; i < inputs.length; i++)
		{
			int id = inputs[i];
			long left = used[i];
			Position p = positions.get(id);
			if (p != null && p.qty > 0 && left > 0)
			{
				long moved = Math.min(left, p.qty);
				long cost = p.totalCost * moved / p.qty;
				p.qty -= moved;
				p.totalCost -= cost;
				if (p.qty <= 0)
				{
					positions.remove(id);
				}
				total += cost;
				left -= moved;

				// The flip follows the items: the input's entry shrinks
				Flip f = openFlip(id);
				if (f != null)
				{
					f.boughtQty -= moved;
					f.boughtCost -= cost;
					if (f.boughtQty <= 0 && f.qty <= 0)
					{
						history.remove(f);
					}
					else if (!positions.containsKey(id))
					{
						f.open = false;
					}
				}
			}
			total += left * Math.max(0, marketEach[i]);
		}

		Position o = positions.get(outId);
		if (o == null)
		{
			positions.put(outId, new Position(outQty, total));
		}
		else
		{
			o.qty += outQty;
			o.totalCost += total;
		}
		Flip of = openFlip(outId);
		if (of == null)
		{
			of = new Flip(now, outId, outName + " (made)");
		}
		of.boughtQty += outQty;
		of.boughtCost += total;
		of.time = now;
		moveToTop(of);
	}

	/** Newest activity first. One entry per flip: from the first buy until everything bought is sold. */
	List<Flip> history = new ArrayList<>();

	Flip openFlip(int itemId)
	{
		for (Flip f : history)
		{
			if (f.open && f.itemId == itemId)
			{
				return f;
			}
		}
		return null;
	}

	void moveToTop(Flip f)
	{
		history.remove(f);
		history.add(0, f);
		while (history.size() > MAX_HISTORY)
		{
			history.remove(history.size() - 1);
		}
	}

	static class Position
	{
		long qty;
		long totalCost;

		Position(long qty, long totalCost)
		{
			this.qty = qty;
			this.totalCost = totalCost;
		}
	}

	static class SlotSnapshot
	{
		int itemId;
		boolean buy;
		int qty;
		long spent;

		SlotSnapshot(int itemId, boolean buy, int qty, long spent)
		{
			this.itemId = itemId;
			this.buy = buy;
			this.qty = qty;
			this.spent = spent;
		}
	}

	static class Flip
	{
		/** Last activity. */
		long time;
		long started;
		int itemId;
		String name;
		/** Units sold so far. */
		long qty;
		/** Realised profit so far (after tax). */
		long profit;
		/** Cost of the units sold so far. */
		long cost;
		/** Proceeds after tax of the units sold so far. */
		long proceeds;
		/** Units bought in this flip and what they cost. */
		long boughtQty;
		long boughtCost;
		/** True until everything bought has been sold. */
		boolean open;

		Flip(long now, int itemId, String name)
		{
			this.time = now;
			this.started = now;
			this.itemId = itemId;
			this.name = name;
			this.open = true;
		}

		long avgBuy()
		{
			return boughtQty > 0 ? boughtCost / boughtQty : 0;
		}
	}
}

package com.flipledger;

/**
 * A snapshot of one active GE slot, built on the client thread for the side panel.
 */
class OfferView
{
	enum Status
	{
		ACTIVE,
		COMPLETE,
		CANCELLED
	}

	final int slot;
	final int itemId;
	final String name;
	final boolean buy;
	final Status status;
	final int filled;
	final int total;
	final long price;
	final long spent;
	/** Sells only: average cost of what you're holding, or -1 if unknown (bought before the plugin). */
	final long avgCost;

	OfferView(int slot, int itemId, String name, boolean buy, Status status, int filled, int total, long price, long spent, long avgCost)
	{
		this.slot = slot;
		this.itemId = itemId;
		this.name = name;
		this.buy = buy;
		this.status = status;
		this.filled = filled;
		this.total = total;
		this.price = price;
		this.spent = spent;
		this.avgCost = avgCost;
	}

	/** Sells only: profit if the whole offer sells at the listed price, after tax. */
	long estProfit()
	{
		long netEach = price - Gp.taxPerItem(price);
		return (netEach - avgCost) * total;
	}

	/** Sells only: lowest price that doesn't lose money. */
	long breakEven()
	{
		long s = Math.max(0, (long) Math.ceil(avgCost / 0.98) - 2);
		while (s - Gp.taxPerItem(s) < avgCost)
		{
			s++;
		}
		return s;
	}
}

package com.flipledger;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

/**
 * Recommended prices for one item, from the cached bulk Wiki prices (no extra requests
 * except the item's week chart, cached for hours).
 */
final class PriceCheck
{
	private static final Color GOLD = new Color(0xF1C40F);
	private static final Color GREEN = new Color(0x2ECC71);
	private static final Color RED = new Color(0xE74C3C);
	private static final Color GRAY = Color.LIGHT_GRAY;

	private PriceCheck()
	{
	}

	static List<PriceCheckOverlay.Line> lines(PriceService prices, int id, boolean sell, int qty, long avgCost,
		boolean applyTax, LedgerData.LimitWindow lw,
		Processing proc, Runnable onTrend)
	{
		List<PriceCheckOverlay.Line> out = new ArrayList<>();
		PriceService.Window h = prices.hour.get(id);
		PriceService.Window f = prices.fiveMin.get(id);
		// Prefer the typical price over the last 30 minutes (one odd trade can't steer it)
		PriceService.Recent r = prices.recent(id, onTrend);
		long seller = r != null && r.seller > 0 ? r.seller : pick(f == null ? 0 : f.low, h == null ? 0 : h.low);
		long buyer = r != null && r.buyer > 0 ? r.buyer : pick(f == null ? 0 : f.high, h == null ? 0 : h.high);
		if (seller <= 0 || buyer <= 0)
		{
			out.add(new PriceCheckOverlay.Line(prices.hourAt == 0 ? "Prices loading..." : "Not enough trades", "", GRAY));
			return out;
		}
		long taxB = applyTax ? Gp.taxPerItem(buyer) : 0;
		long n = Math.max(1, qty);

		if (!sell)
		{
			long each = buyer - taxB - seller;
			long maxBid = buyer - taxB - Math.max(1, Math.round(seller * 0.005));
			out.add(new PriceCheckOverlay.Line("Buy at", String.format("%,d", seller), GOLD));
			out.add(new PriceCheckOverlay.Line("Sell later at", String.format("%,d", buyer), GREEN));
			boolean thin = maxBid < seller;
			out.add(new PriceCheckOverlay.Line("Don't bid above", maxBid > 0 ? String.format("%,d", maxBid) : "-", thin ? RED : GRAY));
			if (thin)
			{
				out.add(new PriceCheckOverlay.Line("Margin too thin", "skip / lowball", RED));
			}
			out.add(new PriceCheckOverlay.Line("Profit each", Gp.signed(each), each > 0 ? GREEN : RED));
			out.add(new PriceCheckOverlay.Line("x " + String.format("%,d", n), Gp.signed(each * n), each > 0 ? GREEN : RED));
			out.add(new PriceCheckOverlay.Line("Break-even", String.format("%,d", Suggester.breakEven(seller)), GRAY));
			limitLines(out, prices, id, qty, lw);
		}
		else
		{
			out.add(new PriceCheckOverlay.Line("List at", String.format("%,d", buyer), GREEN));
			if (avgCost > 0)
			{
				long each = buyer - taxB - avgCost;
				long be = Suggester.breakEven(avgCost);
				out.add(new PriceCheckOverlay.Line("You paid", String.format("%,d", avgCost), GRAY));
				out.add(new PriceCheckOverlay.Line("Break-even", String.format("%,d", be), GRAY));
				out.add(new PriceCheckOverlay.Line("Profit each", Gp.signed(each), each >= 0 ? GREEN : RED));
				out.add(new PriceCheckOverlay.Line("x " + String.format("%,d", n), Gp.signed(each * n), each >= 0 ? GREEN : RED));
				if (buyer < be)
				{
					out.add(new PriceCheckOverlay.Line("Buyers below BE", "hold or cut", RED));
				}
			}
			else
			{
				out.add(new PriceCheckOverlay.Line("Cost", "unknown", GRAY));
			}
			out.add(new PriceCheckOverlay.Line("Instant sale ~", String.format("%,d", seller), GRAY));
		}

		processLines(out, proc, id, sell ? (avgCost > 0 ? avgCost : -1) : seller, buyer - taxB, n, prices);

		// Latest single trade vs the 30-minute typical: catches a crash in progress
		PriceService.Latest l = prices.latestFor(id);
		if (l != null && l.high > 0)
		{
			long ago = Math.max(0, System.currentTimeMillis() / 1000 - l.highTime);
			String when = ago < 60 ? ago + "s ago" : (ago / 60) + "m ago";
			boolean dropping = l.high < buyer * 0.97 && ago < 600;
			out.add(new PriceCheckOverlay.Line("Latest buyer", String.format("%,d · %s", l.high, when), dropping ? RED : GRAY));
			if (dropping)
			{
				out.add(new PriceCheckOverlay.Line(sell ? "Dropping now" : "Dropping now: wait", String.format("%.1f%%", (l.high / (double) buyer - 1) * 100), RED));
			}
		}

		PriceService.Trend t = prices.trend(id, onTrend);
		if (t != null)
		{
			String[] c = Suggester.classify(t.mids);
			Color col = "steady".equals(c[0]) ? GREEN : "settled".equals(c[0]) ? GOLD : ("unchecked".equals(c[0]) ? GRAY : RED);
			String verdict = c[0];
			if (!sell && ("sliding".equals(c[0]) || "spiking".equals(c[0])))
			{
				verdict = c[0] + ": skip";
			}
			out.add(new PriceCheckOverlay.Line("Week", verdict, col));
		}
		else
		{
			out.add(new PriceCheckOverlay.Line("Week", "checking...", GRAY));
		}
		out.add(new PriceCheckOverlay.Line("Volume/hr", h == null ? "-" : String.format("%,d", Math.min(h.highVol, h.lowVol)), GRAY));
		return out;
	}

	/**
	 * "Is there a better way out?" The best thing to make from this item (up to three steps), what each
	 * unit is worth that way, and how that compares with selling it as it is.
	 * {@code cost} is what each one cost you (or will cost), {@code asIsNet} what one sells for now after tax.
	 */
	private static void processLines(List<PriceCheckOverlay.Line> out, Processing proc, int id, long cost,
		long asIsNet, long n, PriceService prices)
	{
		if (proc == null)
		{
			return;
		}
		Processing.Path p = proc.best(id);
		if (p != null && !p.steps.isEmpty() && p.valueEach > asIsNet * 1.01 + 1)
		{
			out.add(new PriceCheckOverlay.Line("Better: make", short_(name(prices, p.steps.get(p.steps.size() - 1).o)), GOLD));
			if (p.steps.size() > 1)
			{
				StringBuilder via = new StringBuilder();
				for (int i = 0; i < p.steps.size() - 1; i++)
				{
					via.append(i > 0 ? " > " : "").append(name(prices, p.steps.get(i).o));
				}
				out.add(new PriceCheckOverlay.Line("via", short_(via.toString()), GRAY));
			}
			java.util.LinkedHashSet<String> where = new java.util.LinkedHashSet<>();
			for (Recipes.Recipe r : p.steps)
			{
				if (r.f != null && !r.f.isEmpty())
				{
					where.add(r.f);
				}
			}
			if (!where.isEmpty())
			{
				out.add(new PriceCheckOverlay.Line("at", short_(String.join(", ", where)), GRAY));
			}
			long each = Math.round(p.valueEach) - (cost > 0 ? cost : 0);
			if (cost > 0)
			{
				out.add(new PriceCheckOverlay.Line("Made + sold each", Gp.signed(each), each > 0 ? GREEN : RED));
				out.add(new PriceCheckOverlay.Line("x " + String.format("%,d", n), Gp.signed(each * n), each > 0 ? GREEN : RED));
			}
			out.add(new PriceCheckOverlay.Line("vs selling as is", Gp.signed(Math.round(p.valueEach) - asIsNet) + " each", GREEN));
		}
		else
		{
			Processing.Path locked = proc.bestIgnoringLevels(id);
			if (locked != null && locked.needs != null && locked.valueEach > asIsNet * 1.01 + 1)
			{
				out.add(new PriceCheckOverlay.Line("Could make " + short_(name(prices, locked.steps.get(locked.steps.size() - 1).o)),
					"needs " + locked.needs, GRAY));
			}
		}
	}

	private static String name(PriceService prices, int id)
	{
		PriceService.Item it = prices.mapping.get(id);
		return it == null ? "item" : it.name;
	}

	private static String short_(String s)
	{
		return s.length() > 22 ? s.substring(0, 21) + "…" : s;
	}

	/** Buy limit left in this 4-hour window, and a warning if the offer asks for more than that. */
	private static void limitLines(List<PriceCheckOverlay.Line> out, PriceService prices, int id, int qty,
		LedgerData.LimitWindow lw)
	{
		PriceService.Item it = prices.mapping.get(id);
		int limit = it != null && it.limit > 0 ? it.limit : (lw != null ? lw.limit : 0);
		if (limit <= 0)
		{
			return;
		}
		long bought = lw == null ? 0 : lw.bought;
		long left = Math.max(0, limit - bought);
		Color c = left == 0 ? RED : bought > 0 ? GOLD : GRAY;
		out.add(new PriceCheckOverlay.Line("Buy limit left", String.format("%,d / %,d", left, limit), c));
		if (lw != null)
		{
			out.add(new PriceCheckOverlay.Line("Limit resets", Gp.clock(lw.start + LedgerData.LIMIT_WINDOW_MS), GRAY));
		}
		if (qty > left)
		{
			out.add(new PriceCheckOverlay.Line(left == 0 ? "Limit reached" : "Over limit",
				left == 0 ? "won't fill yet" : String.format("only %,d fill", left), RED));
		}
	}

	/** Latest 5-minute price when there is one, otherwise the hour average. */
	private static long pick(long fiveMin, long hour)
	{
		return fiveMin > 0 ? fiveMin : hour;
	}
}

package com.flipledger;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Shown while you're setting up a GE offer: recommended prices for the item you picked.
 * Display only: you type the price yourself. Drag it anywhere (Alt + drag).
 */
class PriceCheckOverlay extends OverlayPanel
{
	static class Line
	{
		final String left;
		final String right;
		final Color color;

		Line(String left, String right, Color color)
		{
			this.left = left;
			this.right = right;
			this.color = color;
		}
	}

	private volatile String title;
	private volatile List<Line> lines = Collections.emptyList();

	@Inject
	PriceCheckOverlay()
	{
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(net.runelite.client.ui.overlay.OverlayLayer.ABOVE_WIDGETS); // stay on top of the GE window
	}

	void show(String title, List<Line> lines)
	{
		this.title = title;
		this.lines = lines;
	}

	void hide()
	{
		this.title = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		String t = title;
		if (t == null)
		{
			return null;
		}
		panelComponent.setPreferredSize(new Dimension(235, 0));
		panelComponent.getChildren().add(TitleComponent.builder().text(t).color(Color.WHITE).build());
		for (Line l : lines)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(l.left).right(l.right).rightColor(l.color == null ? Color.WHITE : l.color).build());
		}
		return super.render(g);
	}
}

package com.flipledger;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Downloads public prices from the OSRS Wiki real-time price API, kept deliberately light:
 * bulk files only (one request covers every item), long refresh intervals, and per-item
 * history only for a handful of top candidates, cached for hours.
 */
class PriceService
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(PriceService.class);
	private static final String BASE = "https://prices.runescape.wiki/api/v1/osrs/";
	private static final String USER_AGENT = "Flip Ledger RuneLite plugin - consumable flip suggestions";

	static final long HOUR_INTERVAL = 10 * 60_000L;      // /1h and /5m
	static final long DAY_INTERVAL = 30 * 60_000L;       // /24h
	static final long MAPPING_INTERVAL = 24 * 3600_000L; // /mapping
	static final long TREND_TTL = 2 * 3600_000L;         // per-item 6h history

	static class Item
	{
		int id;
		String name;
		boolean members;
		int limit;
	}

	static class Window
	{
		long high;   // average price buyers paid (you sell here)
		long low;    // average price sellers got (you buy here)
		long highVol;
		long lowVol;
	}

	private final OkHttpClient http;
	private final Gson gson;

	volatile Map<Integer, Item> mapping = Collections.emptyMap();
	volatile Map<Integer, Window> hour = Collections.emptyMap();
	volatile Map<Integer, Window> fiveMin = Collections.emptyMap();
	volatile Map<Integer, Window> day = Collections.emptyMap();
	volatile long hourAt;
	volatile long dayAt;
	private volatile long mappingAt;
	private final Map<Integer, Trend> trends = new ConcurrentHashMap<>();
	private final Map<String, Boolean> inFlight = new ConcurrentHashMap<>();

	static class Trend
	{
		final long at;
		final List<Long> mids;

		Trend(long at, List<Long> mids)
		{
			this.at = at;
			this.mids = mids;
		}
	}

	PriceService(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	/** Fetch whatever is due. onChange runs (on an OkHttp thread) after each file arrives. */
	void refreshDue(Runnable onChange, boolean force)
	{
		long now = System.currentTimeMillis();
		if (force || now - mappingAt > MAPPING_INTERVAL || mapping.isEmpty())
		{
			get("mapping", body -> {
				Map<Integer, Item> m = new HashMap<>();
				for (JsonElement e : gson.fromJson(body, JsonArray.class))
				{
					JsonObject o = e.getAsJsonObject();
					Item it = new Item();
					it.id = o.get("id").getAsInt();
					it.name = o.get("name").getAsString();
					it.members = o.has("members") && o.get("members").getAsBoolean();
					it.limit = o.has("limit") && !o.get("limit").isJsonNull() ? o.get("limit").getAsInt() : 0;
					m.put(it.id, it);
				}
				mapping = m;
				mappingAt = System.currentTimeMillis();
				onChange.run();
			});
		}
		if (force || now - hourAt > HOUR_INTERVAL)
		{
			get("1h", body -> {
				hour = windows(body);
				hourAt = System.currentTimeMillis();
				onChange.run();
			});
			get("5m", body -> {
				fiveMin = windows(body);
				onChange.run();
			});
		}
		if (force || now - dayAt > DAY_INTERVAL)
		{
			get("24h", body -> {
				day = windows(body);
				dayAt = System.currentTimeMillis();
				onChange.run();
			});
		}
	}

	/** Cached week history (28 x 6h mid prices) or null; requests it if missing/stale. */
	Trend trend(int id, Runnable onChange)
	{
		Trend t = trends.get(id);
		if (t != null && System.currentTimeMillis() - t.at < TREND_TTL)
		{
			return t;
		}
		get("timeseries?timestep=6h&id=" + id, body -> {
			JsonArray arr = gson.fromJson(body, JsonObject.class).getAsJsonArray("data");
			List<Long> mids = new ArrayList<>();
			int start = Math.max(0, arr.size() - 28);
			for (int i = start; i < arr.size(); i++)
			{
				JsonObject o = arr.get(i).getAsJsonObject();
				long hi = num(o, "avgHighPrice");
				long lo = num(o, "avgLowPrice");
				if (hi > 0 && lo > 0)
				{
					mids.add((hi + lo) / 2);
				}
			}
			trends.put(id, new Trend(System.currentTimeMillis(), mids));
			onChange.run();
		});
		return t; // stale copy (or null) until the new one arrives
	}

	static final long RECENT_TTL = 60_000L;

	/** Most recent single trades: the fastest signal that a price is moving. */
	static class Latest
	{
		long high;     // last price a buyer paid
		long highTime; // unix seconds
		long low;      // last price a seller got
		long lowTime;
	}

	private final Map<Integer, Latest> latest = new ConcurrentHashMap<>();
	private final Map<Integer, Long> latestAt = new ConcurrentHashMap<>();

	Latest latestFor(int id)
	{
		return latest.get(id);
	}

	/** Refresh latest trades: one tiny request for a single item, one bulk request for several. */
	void refreshLatest(java.util.Collection<Integer> ids, long maxAgeMs, Runnable onChange)
	{
		long now = System.currentTimeMillis();
		List<Integer> stale = new ArrayList<>();
		for (int id : ids)
		{
			Long at = latestAt.get(id);
			if (at == null || now - at > maxAgeMs)
			{
				stale.add(id);
			}
		}
		if (stale.isEmpty())
		{
			return;
		}
		String path = stale.size() == 1 ? "latest?id=" + stale.get(0) : "latest";
		get(path, body -> {
			JsonObject data = gson.fromJson(body, JsonObject.class).getAsJsonObject("data");
			long t = System.currentTimeMillis();
			for (int id : stale)
			{
				JsonElement e = data.get(String.valueOf(id));
				if (e == null || !e.isJsonObject())
				{
					continue;
				}
				JsonObject o = e.getAsJsonObject();
				Latest l = new Latest();
				l.high = num(o, "high");
				l.highTime = num(o, "highTime");
				l.low = num(o, "low");
				l.lowTime = num(o, "lowTime");
				latest.put(id, l);
				latestAt.put(id, t);
			}
			onChange.run();
		});
	}

	private final Map<Integer, Recent> recents = new ConcurrentHashMap<>();

	/** Typical (median) seller and buyer price over the last 30 minutes. */
	static class Recent
	{
		final long at;
		final long seller;
		final long buyer;

		Recent(long at, long seller, long buyer)
		{
			this.at = at;
			this.seller = seller;
			this.buyer = buyer;
		}
	}

	/** Cached 30-minute typical prices for one item (only for the item you're making an offer for). */
	Recent recent(int id, Runnable onChange)
	{
		Recent r = recents.get(id);
		if (r != null && System.currentTimeMillis() - r.at < RECENT_TTL)
		{
			return r;
		}
		get("timeseries?timestep=5m&id=" + id, body -> {
			JsonArray arr = gson.fromJson(body, JsonObject.class).getAsJsonArray("data");
			List<Long> lows = new ArrayList<>(), highs = new ArrayList<>();
			for (int i = Math.max(0, arr.size() - 6); i < arr.size(); i++)
			{
				JsonObject o = arr.get(i).getAsJsonObject();
				long lo = num(o, "avgLowPrice"), hi = num(o, "avgHighPrice");
				if (lo > 0)
				{
					lows.add(lo);
				}
				if (hi > 0)
				{
					highs.add(hi);
				}
			}
			recents.put(id, new Recent(System.currentTimeMillis(), median(lows), median(highs)));
			if (recents.size() > 200)
			{
				recents.clear();
			}
			onChange.run();
		});
		return r;
	}

	private static long median(List<Long> v)
	{
		if (v.isEmpty())
		{
			return 0;
		}
		List<Long> s = new ArrayList<>(v);
		Collections.sort(s);
		int m = s.size() / 2;
		return s.size() % 2 == 1 ? s.get(m) : (s.get(m - 1) + s.get(m)) / 2;
	}

	private Map<Integer, Window> windows(Reader body)
	{
		JsonObject data = gson.fromJson(body, JsonObject.class).getAsJsonObject("data");
		Map<Integer, Window> out = new HashMap<>();
		for (Map.Entry<String, JsonElement> e : data.entrySet())
		{
			JsonObject o = e.getValue().getAsJsonObject();
			Window w = new Window();
			w.high = num(o, "avgHighPrice");
			w.low = num(o, "avgLowPrice");
			w.highVol = num(o, "highPriceVolume");
			w.lowVol = num(o, "lowPriceVolume");
			out.put(Integer.parseInt(e.getKey()), w);
		}
		return out;
	}

	private static long num(JsonObject o, String k)
	{
		JsonElement e = o.get(k);
		return e == null || e.isJsonNull() ? 0 : e.getAsLong();
	}

	private interface Handler
	{
		void handle(Reader body) throws Exception;
	}

	private void get(String path, Handler handler)
	{
		if (inFlight.putIfAbsent(path, Boolean.TRUE) != null)
		{
			return;
		}
		Request req = new Request.Builder().url(BASE + path).header("User-Agent", USER_AGENT).build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				inFlight.remove(path);
				log.debug("Flip Ledger: price request failed: {}", path, e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (response.isSuccessful() && body != null)
					{
						handler.handle(body.charStream());
					}
				}
				catch (Exception e)
				{
					log.debug("Flip Ledger: couldn't read {}", path, e);
				}
				finally
				{
					inFlight.remove(path);
				}
			}
		});
	}
}

package com.flipledger;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.ToIntFunction;

/**
 * "Can I turn this into something worth more?" Looks up to three steps ahead
 * (grimy herb -> clean -> unfinished potion -> potion, logs -> shafts -> headless arrows, ore -> bar)
 * using only cached bulk prices.
 */
final class Processing
{
	static final int MAX_STEPS = 3;
	private static final long MIN_HOURLY_VOLUME = 20;      // selling the item as it is
	private static final long PRODUCT_HOURLY_VOLUME = 100; // anything we'd suggest making must sell steadily

	static class Path
	{
		/** What one unit of the starting item is worth at the end, after tax and after buying any other inputs. */
		double valueEach;
		final List<Recipes.Recipe> steps = new ArrayList<>();
		/** Highest unmet skill requirement on this path, e.g. "Herblore 45", or null. */
		String needs;
	}

	private final PriceService prices;
	private final Recipes recipes;
	private final ToIntFunction<String> level;
	private final boolean members;
	private final boolean applyTax;
	/** True: skip recipes you can't make yet. False: allow them and note the level needed. */
	private final boolean strict;
	private final Map<Long, Path> memo = new HashMap<>();

	/** @param level the player's real level by skill name ("Herblore") */
	Processing(PriceService prices, Recipes recipes, ToIntFunction<String> level, boolean members, boolean applyTax)
	{
		this(prices, recipes, level, members, applyTax, true);
	}

	private Processing(PriceService prices, Recipes recipes, ToIntFunction<String> level, boolean members,
		boolean applyTax, boolean strict)
	{
		this.strict = strict;
		this.prices = prices;
		this.recipes = recipes;
		this.level = level;
		this.members = members;
		this.applyTax = applyTax;
	}

	/** What one unit sells for right now after tax (cautious price), or 0 if it barely trades. */
	double sellNet(int id)
	{
		PriceService.Window h = prices.hour.get(id);
		if (h == null || h.high <= 0 || Math.min(h.highVol, h.lowVol) < MIN_HOURLY_VOLUME)
		{
			return 0;
		}
		return cautious(id, h);
	}

	/** Like sellNet, but stricter for things you'd make: it must sell steadily (busy, and a tight buy/sell gap). */
	private double productNet(int id)
	{
		PriceService.Window h = prices.hour.get(id);
		if (h == null || h.high <= 0 || h.low <= 0 || Math.min(h.highVol, h.lowVol) < PRODUCT_HOURLY_VOLUME
			|| h.high - h.low > h.high * 0.15)
		{
			return 0;
		}
		return cautious(id, h);
	}

	private double cautious(int id, PriceService.Window h)
	{
		long p = h.high;
		PriceService.Window f = prices.fiveMin.get(id);
		if (f != null && f.high > 0)
		{
			p = Math.min(p, f.high);
		}
		return p - (applyTax ? Gp.taxPerItem(p) : 0);
	}

	/** What one unit costs to buy (cautious: the price buyers have been paying), or -1 if unknown. */
	long buyCost(int id)
	{
		if (id == 995)
		{
			return 1; // coins (sawmill fees and similar)
		}
		PriceService.Window h = prices.hour.get(id);
		PriceService.Window f = prices.fiveMin.get(id);
		long a = h == null ? 0 : h.high, b = f == null ? 0 : f.high;
		long p = Math.max(a, b);
		return p > 0 ? p : -1;
	}

	/** Best way to process this item (at least one step), or null if nothing is worth it or possible. */
	Path best(int id)
	{
		return process(id, MAX_STEPS, true);
	}

	/** Same, ignoring your levels: to show "you'd need Herblore 45 for something better". */
	Path bestIgnoringLevels(int id)
	{
		return new Processing(prices, recipes, level, members, applyTax, false).process(id, MAX_STEPS, true);
	}

	private Path process(int id, int depth, boolean mustProcess)
	{
		long key = id * 8L + depth * 2L + (mustProcess ? 1 : 0);
		if (memo.containsKey(key))
		{
			return memo.get(key);
		}
		memo.put(key, null); // guards against recipe loops
		Path best = null;
		if (!mustProcess)
		{
			double s = productNet(id);
			if (s > 0)
			{
				best = new Path();
				best.valueEach = s;
			}
		}
		if (depth > 0)
		{
			for (Recipes.Recipe r : recipes.using(id))
			{
				PriceService.Item out = prices.mapping.get(r.o);
				if (out == null || (out.members && !members))
				{
					continue;
				}
				String unmet = unmet(r);
				if (unmet != null && strict)
				{
					continue;
				}
				double mine = r.qtyOf(id);
				double others = 0;
				boolean priced = true;
				for (double[] x : r.m)
				{
					if ((int) x[0] == id)
					{
						continue;
					}
					long c = buyCost((int) x[0]);
					if (c < 0)
					{
						priced = false;
						break;
					}
					others += c * x[1];
				}
				if (!priced || mine <= 0)
				{
					continue;
				}
				Path next = process(r.o, depth - 1, false);
				if (next == null)
				{
					continue;
				}
				double value = (r.q * next.valueEach - others) / mine;
				if (best == null || value > best.valueEach)
				{
					best = new Path();
					best.valueEach = value;
					best.steps.add(r);
					best.steps.addAll(next.steps);
					best.needs = unmet != null ? unmet : next.needs;
				}
			}
		}
		memo.put(key, best);
		return best;
	}

	/** First skill requirement the player doesn't meet, e.g. "Herblore 45", or null. */
	private String unmet(Recipes.Recipe r)
	{
		if (r.s == null)
		{
			return null;
		}
		for (Object[] s : r.s)
		{
			String skill = String.valueOf(s[0]);
			int need = ((Number) s[1]).intValue();
			if (level.applyAsInt(skill) < need)
			{
				return Character.toUpperCase(skill.charAt(0)) + skill.substring(1) + " " + need;
			}
		}
		return null;
	}
}

package com.flipledger;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * What can be made from what, bundled with the plugin (taken from the OSRS Wiki's recipe data,
 * only recipes where every input and the output trade on the GE). No network requests.
 */
final class Recipes
{
	static class Recipe
	{
		/** Output item, how many one action makes. */
		int o;
		double q;
		/** Inputs: [itemId, quantity] per action. */
		double[][] m;
		/** Skill requirements: [name, level]. */
		Object[][] s;
		/** Where it's made, e.g. "Furnace" (may be empty). */
		String f;

		double qtyOf(int itemId)
		{
			for (double[] x : m)
			{
				if ((int) x[0] == itemId)
				{
					return x[1];
				}
			}
			return 0;
		}
	}

	private final Map<Integer, List<Recipe>> byOutput = new HashMap<>();
	private final Map<Integer, List<Recipe>> byInput = new HashMap<>();

	Recipes(Gson gson)
	{
		List<Recipe> all = Collections.emptyList();
		try (InputStream in = Recipes.class.getResourceAsStream("recipes.json"))
		{
			if (in != null)
			{
				all = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
					new TypeToken<List<Recipe>>()
					{
					}.getType());
			}
		}
		catch (Exception ignored)
		{
			// No recipes: processing tips and cost carry-over are simply off
		}
		for (Recipe r : all)
		{
			byOutput.computeIfAbsent(r.o, k -> new ArrayList<>()).add(r);
			for (double[] x : r.m)
			{
				byInput.computeIfAbsent((int) x[0], k -> new ArrayList<>()).add(r);
			}
		}
	}

	List<Recipe> making(int outputId)
	{
		return byOutput.getOrDefault(outputId, Collections.emptyList());
	}

	List<Recipe> using(int inputId)
	{
		return byInput.getOrDefault(inputId, Collections.emptyList());
	}
}

