	// ---------- stats + flips ----------

	void update(long profit, int flipsDone, long sessionMs, LedgerData data)
	{
		sessionProfit.setText(Gp.signed(profit));
		sessionProfit.setForeground(Gp.color(profit));
		double hours = sessionMs / 3_600_000.0;
		long perHour = hours > 0.02 ? Math.round(profit / hours) : 0;
		gpHour.setText(Gp.shortGp(perHour));
		gpHour.setForeground(Gp.color(perHour));
		sessionFlips.setText(String.valueOf(flipsDone));
		long mins = sessionMs / 60_000;
		sessionTime.setText(String.format("%d:%02d", mins / 60, mins % 60));
		if (data == null)
		{
			allTime.setText("log in");
			allTime.setForeground(Color.GRAY);
		}
		else
		{
			allTime.setText(Gp.shortGp(data.allTimeProfit));
			allTime.setForeground(Gp.color(data.allTimeProfit));
		}
		lastData = data;
		renderFlips();
		renderLimits();
	}

	/** Items bought in the last 4 hours: how much of the GE buy limit is used and when it resets. */
	private void renderLimits()
	{
		limitsList.removeAll();
		List<LedgerData.LimitWindow> list = lastData == null ? Collections.emptyList()
			: lastData.activeLimits(System.currentTimeMillis());
		if (list.isEmpty())
		{
			empty(limitsList, "Nothing bought in the last 4 hours");
		}
		for (LedgerData.LimitWindow w : list)
		{
			long reset = w.start + LedgerData.LIMIT_WINDOW_MS;
			boolean full = w.limit > 0 && w.bought >= w.limit;
			JPanel row = new JPanel(new BorderLayout(4, 0));
			row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			row.setBorder(new EmptyBorder(3, 6, 3, 6));
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
			JLabel name = new JLabel(w.name == null ? "Item" : w.name);
			name.setForeground(Color.WHITE);
			JLabel amt = new JLabel(w.limit > 0
				? Gp.shortGp(w.bought) + "/" + Gp.shortGp(w.limit) : Gp.shortGp(w.bought));
			amt.setForeground(full ? RISKY : Color.LIGHT_GRAY);
			row.add(name, BorderLayout.CENTER);
			row.add(amt, BorderLayout.EAST);
			row.setToolTipText(String.format("<html>%s<br>Bought %,d%s<br>Resets in %s</html>",
				(w.name == null ? "Item" : w.name).replace("<", "&lt;"), w.bought,
				w.limit > 0 ? String.format(" of %,d (%,d left)", w.limit, Math.max(0, w.limit - w.bought)) : "",
				Gp.clock(reset)));
			limitsList.add(row);
			limitsList.add(Box.createVerticalStrut(2));
		}
		limitsList.revalidate();
		limitsList.repaint();
	}

	private void renderFlips()
	{
		flips.removeAll();
		LedgerData data = lastData;
		if (data == null || data.history.isEmpty())
		{
			empty(flips, data == null ? "Log in to see your flips." : "No flips yet. Buy something on the GE and it shows up here.");
		}
		else
		{
			int shown = 0;
			for (LedgerData.Flip f : new ArrayList<>(data.history))
			{
				if (f.qty <= 0)
				{
					continue; // nothing sold yet: it's on the Offers tab
				}
				flipRow(f);
				if (++shown >= SHOWN_FLIPS)
				{
					break;
				}
			}
			if (shown == 0)
			{
				empty(flips, "No sales yet. Completed flips show up here.");
			}
		}
		flips.revalidate();
		flips.repaint();
	}

	/** One line per flip: "1,000 x Item" and a green + or red - profit. Details on hover. */
	private void flipRow(LedgerData.Flip f)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		JLabel name = new JLabel(String.format("%s x %s", Gp.shortGp(f.qty), f.name));
		name.setForeground(f.open ? Color.LIGHT_GRAY : Color.WHITE);
		JLabel p = new JLabel(Gp.signed(f.profit));
		p.setForeground(Gp.color(f.profit));
		row.add(name, BorderLayout.CENTER);
		row.add(p, BorderLayout.EAST);
		StringBuilder tip = new StringBuilder("<html>").append(f.name.replace("<", "&lt;"));
		if (f.boughtQty > 0)
		{
			tip.append(String.format("<br>Bought %,d @ %,d", f.boughtQty, f.avgBuy()));
		}
		tip.append(String.format("<br>Sold %,d &middot; %s", f.qty, TIME.format(new Date(f.time))));
		if (f.open)
		{
			tip.append("<br><i>Still selling</i>");
		}
		row.setToolTipText(tip.append("</html>").toString());
		flips.add(row);
		flips.add(Box.createVerticalStrut(2));
	}

	/** The Offers tab: current GE offers with progress bars. */
	JPanel offersView()
	{
		JPanel p = section();
		JLabel h = new JLabel("Current offers");
		h.setForeground(Color.WHITE);
		h.setFont(FontManager.getRunescapeBoldFont());
		h.setBorder(new EmptyBorder(4, 0, 6, 0));
		h.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(h);
		p.add(offers);
		JLabel lh = new JLabel("Buy limits (4 hours)");
		lh.setForeground(Color.WHITE);
		lh.setFont(FontManager.getRunescapeBoldFont());
		lh.setBorder(new EmptyBorder(12, 0, 6, 0));
		lh.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(lh);
		p.add(limitsList);
		renderLimits();
		JLabel tip = new JLabel("<html><body style='width:150px'>Hover an offer for price, spent, estimated profit and break-even. Buy limits count only buys made while the plugin is running.</body></html>");
		tip.setForeground(Color.GRAY);
		tip.setBorder(new EmptyBorder(8, 0, 0, 0));
		tip.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(tip);
		return p;
	}

	private void flipCard(LedgerData.Flip f)
	{
		OfferView buying = null, selling = null;
		for (OfferView o : lastOffers)
		{
			if (o.itemId == f.itemId && o.status == OfferView.Status.ACTIVE)
			{
				if (o.buy)
				{
					buying = o;
				}
				else
				{
					selling = o;
				}
			}
		}

		String status;
		Color edge;
		if (!f.open)
		{
			status = "Done";
			edge = Gp.color(f.profit);
		}
		else if (selling != null)
		{
			status = "Selling";
			edge = Gp.PROFIT;
		}
		else if (buying != null)
		{
			status = "Buying";
			edge = GeSlotTextOverlay.BOUGHT;
		}
		else
		{
			status = f.qty > 0 ? "Part sold" : "Holding";
			edge = Color.GRAY;
		}

		JPanel c = card(edge);
		JPanel lines = new JPanel(new GridLayout(0, 1, 0, 1));
		lines.setOpaque(false);
		lines.add(line(f.name, Color.WHITE));

		String bought = f.boughtQty > 0
			? String.format("%,d @ %s", f.boughtQty, Gp.shortGp(f.avgBuy()))
			: "pre-tracking";
		lines.add(line(status + "  ·  " + bought, Color.LIGHT_GRAY));

		int n = 2;
		if (f.qty > 0)
		{
			lines.add(line(String.format("Sold %,d  ·  %s", f.qty, TIME.format(new Date(f.time))), Color.GRAY));
			n++;
		}
		if (f.open && selling != null && f.boughtQty > 0)
		{
			long holding = Math.max(0, f.boughtQty - f.qty);
			long netEach = selling.price - Gp.taxPerItem(selling.price);
			long est = f.profit + (netEach - f.avgBuy()) * holding;
			JLabel l = new JLabel(String.format("<html>At %s: <font color='%s'>%s</font></html>",
				Gp.shortGp(selling.price), est >= 0 ? "#2ecc71" : "#e74c3c", Gp.signed(est)));
			l.setForeground(Color.GRAY);
			lines.add(l);
			n++;
		}
		c.add(lines, BorderLayout.CENTER);

		JLabel p = new JLabel(f.qty > 0 ? Gp.signed(f.profit) : "");
		p.setForeground(Gp.color(f.profit));
		p.setVerticalAlignment(JLabel.TOP);
		c.add(p, BorderLayout.EAST);
		finish(flips, c, n);
	}

	// ---------- current offers ----------

	void updateOffers(List<OfferView> views)
	{
		lastOffers = views == null ? Collections.emptyList() : views;
		offers.removeAll();
		if (lastOffers.isEmpty())
		{
			empty(offers, "No active offers");
		}
		for (OfferView v : lastOffers)
		{
			offers.add(offerRow(v));
			offers.add(Box.createVerticalStrut(2));
		}
		offers.revalidate();
		offers.repaint();
		renderFlips();
		renderLimits();
		renderSuggestion();
	}

	/** One compact row: "Buy  Item" with the filled amount, and a thin progress bar. Details on hover. */
	private JPanel offerRow(OfferView v)
	{
		Color c = v.status == OfferView.Status.CANCELLED ? RISKY : v.buy ? GeSlotTextOverlay.BOUGHT : Gp.PROFIT;
		JPanel row = new JPanel(new BorderLayout(4, 2));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(3, 6, 4, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

		JLabel type = new JLabel(v.buy ? "Buy " : "Sell ");
		type.setForeground(c);
		JLabel name = new JLabel(v.name); // plain label: long names end in "..." instead of wrapping
		name.setForeground(Color.WHITE);
		JPanel left = new JPanel(new BorderLayout());
		left.setOpaque(false);
		left.add(type, BorderLayout.WEST);
		left.add(name, BorderLayout.CENTER);
		String right = v.status == OfferView.Status.COMPLETE ? "collect"
			: v.status == OfferView.Status.CANCELLED ? "cancelled"
			: String.format("%s/%s", Gp.shortGp(v.filled), Gp.shortGp(v.total));
		JLabel amt = new JLabel(right);
		amt.setForeground(v.status == OfferView.Status.COMPLETE ? c : Color.LIGHT_GRAY);
		row.add(left, BorderLayout.CENTER);
		row.add(amt, BorderLayout.EAST);

		double frac = v.total > 0 ? Math.min(1.0, v.filled / (double) v.total) : 0;
		JPanel bar = new JPanel()
		{
			@Override
			protected void paintComponent(java.awt.Graphics g)
			{
				super.paintComponent(g);
				g.setColor(new Color(0x3A3A3A));
				g.fillRect(0, 0, getWidth(), getHeight());
				g.setColor(c);
				g.fillRect(0, 0, (int) Math.round(getWidth() * frac), getHeight());
			}
		};
		bar.setPreferredSize(new Dimension(10, 3));
		row.add(bar, BorderLayout.SOUTH);

		StringBuilder tip = new StringBuilder("<html>").append(v.name.replace("<", "&lt;")).append("<br>")
			.append(String.format("%,d / %,d @ %,d", v.filled, v.total, v.price));
		if (v.buy)
		{
			tip.append("<br>Spent ").append(Gp.shortGp(v.spent)).append(" of ").append(Gp.shortGp(v.price * v.total));
		}
		else if (v.avgCost >= 0)
		{
			tip.append("<br>Est. ").append(Gp.signed(v.estProfit())).append(String.format(" &middot; break-even %,d", v.breakEven()));
		}
		row.setToolTipText(tip.append("</html>").toString());
		return row;
	}

	private static String hex(Color c)
	{
		return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}

	// ---------- suggestions ----------

	void updateSuggestions(List<Suggester.Suggestion> list, String status)
	{
		suggestionStatus.setText(status);
		lastSuggestions = list == null ? Collections.emptyList() : list;
		renderSuggestion();
	}

	/** Shows one suggestion. Skipped, blocked, already-bought and already-held items are passed over. */
	private void renderSuggestion()
	{
		long now = System.currentTimeMillis();
		skipped.values().removeIf(t -> now - t > SKIP_MS);

		Set<Integer> busy = new HashSet<>();
		for (OfferView o : lastOffers)
		{
			busy.add(o.itemId);
		}
		if (lastData != null)
		{
			for (LedgerData.Flip f : lastData.history)
			{
				if (f.open)
				{
					busy.add(f.itemId);
				}
			}
		}

		List<Suggester.Suggestion> left = new ArrayList<>();
		for (Suggester.Suggestion s : lastSuggestions)
		{
			if (!skipped.containsKey(s.id) && !busy.contains(s.id))
			{
				left.add(s);
			}
		}

		suggestions.removeAll();
		if (left.isEmpty())
		{
			empty(suggestions, lastSuggestions.isEmpty()
				? "Nothing passes the checklist right now with your settings. Try a longer fill window, a lower min profit, or more item types."
				: "You've skipped or are already flipping every current suggestion. Skips clear after 30 minutes, or press Refresh.");
		}
		else
		{
			Suggester.Suggestion s = left.get(0);
			Color tag = "steady".equals(s.status) ? STEADY : "settled".equals(s.status) ? SETTLED
				: ("checking".equals(s.status) || "unchecked".equals(s.status)) ? Color.GRAY : RISKY;
			JPanel c = card(tag);
			c.setToolTipText("<html>" + s.status + ": " + s.why + "<br>About " + String.format("%,d", s.perHour)
				+ " trade each way per hour</html>");
			JPanel lines = new JPanel();
			lines.setLayout(new BoxLayout(lines, BoxLayout.Y_AXIS));
			lines.setOpaque(false);
			// Full item name, wrapping if needed: "(e)" and similar matter
			JLabel name = new JLabel("<html><body style='width:140px'>" + s.name.replace("&", "&amp;").replace("<", "&lt;") + "</body></html>");
			name.setForeground(Color.WHITE);
			name.setFont(FontManager.getRunescapeBoldFont());
			lines.add(name);
			lines.add(line("Profit " + Gp.signed(s.profit), Gp.PROFIT));
			lines.add(line(String.format("Buy at %,d", s.buy), GeSlotTextOverlay.BOUGHT));
			lines.add(line(String.format("Sell at %,d", s.sell), Gp.PROFIT));
			lines.add(line(String.format("Qty %,d  ·  %s gp", s.qty, Gp.shortGp(s.cost)), Color.LIGHT_GRAY));
			lines.add(line(String.format("Break-even %,d", s.breakEven), Color.GRAY));
			lines.add(line(String.format("%s  ·  ~%d min/side", s.status, s.fillMinutes), tag));
			c.add(lines, BorderLayout.CENTER);
			suggestions.add(c);
			suggestions.add(Box.createVerticalStrut(3));

			JPanel actions = new JPanel(new GridLayout(1, 2, 6, 0));
			actions.setBackground(ColorScheme.DARK_GRAY_COLOR);
			actions.setAlignmentX(Component.LEFT_ALIGNMENT);
			actions.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
			JButton skip = new JButton("Skip");
			skip.setToolTipText("Show the next suggestion (this one comes back in 30 minutes)");
			skip.addActionListener(e ->
			{
				skipped.put(s.id, System.currentTimeMillis());
				renderSuggestion();
			});
			JButton block = new JButton("Block");
			block.setToolTipText("Never suggest this item again (undo in Settings)");
			block.addActionListener(e ->
			{
				skipped.put(s.id, System.currentTimeMillis()); // hide straight away
				onBlock.accept(s.id);
				renderSuggestion();
			});
			actions.add(skip);
			actions.add(block);
			suggestions.add(actions);

			JLabel hint = new JLabel(String.format("<html><body style='width:150px'>%d of %d. Place the buy yourself; this moves on once it's in the GE.</body></html>",
				1, left.size()));
			hint.setForeground(Color.GRAY);
			hint.setBorder(new EmptyBorder(4, 0, 0, 0));
			hint.setAlignmentX(Component.LEFT_ALIGNMENT);
			suggestions.add(hint);
		}
		suggestions.revalidate();
		suggestions.repaint();
	}
}

package com.flipledger;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Session settings people can change any time. Values are saved in RuneLite's config,
 * so they also appear (and stay in sync) in the plugin's normal settings page.
 */
class SettingsTab extends JPanel
{
	private final ConfigManager configManager;
	private final FlipLedgerConfig config;
	private final Runnable onChange;

	SettingsTab(ConfigManager configManager, FlipLedgerConfig config, Runnable onChange)
	{
		this.configManager = configManager;
		this.config = config;
		this.onChange = onChange;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		build();
	}

	/** Re-read values, e.g. after they were changed on the RuneLite settings page. */
	void reload()
	{
		removeAll();
		build();
		revalidate();
		repaint();
	}

	private void build()
	{
		header("Flipping session");
		gpField("GP to use", "budget", config::budget, "Total gp suggestions may use");
		gpField("Max per slot", "maxPerSlot", config::maxPerSlot, "Most gp in one item");
		gpField("Min profit", "minProfit", config::minProfit, "Smallest profit worth a slot");

		JComboBox<FlipLedgerConfig.FillWindow> fill = new JComboBox<>(FlipLedgerConfig.FillWindow.values());
		fill.setSelectedItem(config.fillWindow());
		fill.addActionListener(e -> set("fillWindow", ((FlipLedgerConfig.FillWindow) fill.getSelectedItem()).name()));
		row("Fill window", fill);

		check("Show risky items", "showRisky", config.showRisky());
		check("Suggestions (Wiki prices)", "suggestions", config.suggestions());
		int blockedCount = config.blockedItems().trim().isEmpty() ? 0 : config.blockedItems().split(",").length;
		javax.swing.JButton unblock = new javax.swing.JButton("Unblock all (" + blockedCount + ")");
		unblock.setAlignmentX(Component.LEFT_ALIGNMENT);
		unblock.addActionListener(e ->
		{
			set("blockedItems", "");
			unblock.setText("Unblock all (0)");
		});
		add(unblock);

		header("Item types");
		check("Potions", "catPotions", config.catPotions());
		check("Food", "catFood", config.catFood());
		check("Runes", "catRunes", config.catRunes());
		check("Ammo", "catAmmo", config.catAmmo());
		check("Herbs & secondaries", "catHerbs", config.catHerbs());
		check("Seeds & saplings", "catSeeds", config.catSeeds());
		check("Bones & ashes", "catBones", config.catBones());
		check("Teleports", "catTeleports", config.catTeleports());
		check("Other supplies", "catSupplies", config.catSupplies());

		header("Display");
		check("Price check while making offers", "showPriceCheck", config.showPriceCheck());
		check("Price drop alerts", "crashAlerts", config.crashAlerts());
		check("Floating text on player", "showFloatingText", config.showFloatingText());
		check("Floating text on GE offers", "showOnGeSlots", config.showOnGeSlots());
		check("Chat message per sale", "showChatMessage", config.showChatMessage());
		check("Subtract 2% GE tax", "applyTax", config.applyTax());

		header("Crew leaderboard");
		check("Share with crew leaderboard", "crewEnabled", config.crewEnabled());
		textField("Submit URL", "crewUrl", config::crewUrl, false, "From your crew leader, starts with https://");
		textField("Crew key", "crewKey", config::crewKey, true, "The crew key from your crew leader");
		JLabel crewNote = new JLabel("<html><body style='width:150px'>Off by default. When on, sends only your name, "
			+ "profit and flip count for the current 1h / 12h / 24h windows (Eastern time), at most once a minute.</body></html>");
		crewNote.setForeground(Color.GRAY);
		crewNote.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(crewNote);

		JLabel note = new JLabel("<html><body style='width:150px'>Members items are hidden automatically on free-to-play worlds.</body></html>");
		note.setForeground(Color.GRAY);
		note.setBorder(BorderFactory.createEmptyBorder(10, 2, 0, 0));
		note.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(note);
	}

	private void header(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(Color.WHITE);
		l.setBorder(BorderFactory.createEmptyBorder(10, 0, 4, 0));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(l);
	}

	private void row(String label, Component field)
	{
		JPanel r = new JPanel(new BorderLayout(6, 0));
		r.setBackground(ColorScheme.DARK_GRAY_COLOR);
		r.setAlignmentX(Component.LEFT_ALIGNMENT);
		r.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		JLabel l = new JLabel(label);
		l.setForeground(Color.LIGHT_GRAY);
		l.setPreferredSize(new Dimension(80, 24));
		r.add(l, BorderLayout.WEST);
		r.add(field, BorderLayout.CENTER);
		add(r);
		add(Box.createVerticalStrut(4));
	}

	private void gpField(String label, String key, Supplier<String> current, String tip)
	{
		JTextField f = new JTextField(current.get());
		f.setToolTipText(tip + ". Use k / m, e.g. 750k or 10m");
		Runnable commit = () ->
		{
			String v = f.getText().trim();
			if (Suggester.parse(v, -1) < 0)
			{
				f.setText(current.get()); // invalid: put the old value back
				return;
			}
			if (!v.equalsIgnoreCase(current.get()))
			{
				set(key, v);
			}
		};
		f.addActionListener(e -> commit.run());
		f.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				commit.run();
			}
		});
		row(label, f);
	}

	private void textField(String label, String key, Supplier<String> current, boolean secret, String tip)
	{
		JTextField f = secret ? new javax.swing.JPasswordField(current.get()) : new JTextField(current.get());
		f.setToolTipText(tip);
		Runnable commit = () ->
		{
			String v = f.getText().trim();
			if (!v.equals(current.get()))
			{
				set(key, v);
			}
		};
		f.addActionListener(e -> commit.run());
		f.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				commit.run();
			}
		});
		row(label, f);
	}

	private void check(String label, String key, boolean value)
	{
		JCheckBox c = new JCheckBox(label, value);
		c.setBackground(ColorScheme.DARK_GRAY_COLOR);
		c.setForeground(Color.LIGHT_GRAY);
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		c.addActionListener(e -> set(key, String.valueOf(c.isSelected())));
		add(c);
	}

	private void set(String key, String value)
	{
		configManager.setConfiguration(FlipLedgerConfig.GROUP, key, value);
		onChange.run();
	}
}

package com.flipledger;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Picks consumable flips using the same rules as the Steady Flips checklist,
 * from bulk price data only (plus cached week history for the top few).
 */
class Suggester
{
	static final int TREND_CANDIDATES = 8;
	static final int SHOWN = 10;

	static class Suggestion
	{
		int id;
		String name;
		long buy;
		long sell;
		long qty;
		long profit;
		long cost;
		long breakEven;
		long perHour;
		int fillMinutes;
		String status; // steady, settled, checking...
		String why;
	}

	static List<Suggestion> compute(PriceService prices, FlipLedgerConfig cfg, boolean membersWorld,
		java.util.function.IntToLongFunction boughtRecently, Runnable onTrend)
	{
		List<Suggestion> out = new ArrayList<>();
		if (prices.mapping.isEmpty() || prices.hour.isEmpty())
		{
			return out;
		}

		long budget = parse(cfg.budget(), 50_000_000L);
		long perSlot = Math.min(budget, parse(cfg.maxPerSlot(), 10_000_000L));
		long minProfit = parse(cfg.minProfit(), 25_000L);
		int minutes = cfg.fillWindow().minutes;

		java.util.Set<Integer> blocked = new java.util.HashSet<>();
		for (String b : cfg.blockedItems().split(","))
		{
			try
			{
				blocked.add(Integer.parseInt(b.trim()));
			}
			catch (NumberFormatException ignored)
			{
			}
		}

		List<Suggestion> candidates = new ArrayList<>();
		for (PriceService.Item it : prices.mapping.values())
		{
			if (it.limit <= 0 || (it.members && !membersWorld) || blocked.contains(it.id))
			{
				continue;
			}
			Consumables.Group g = Consumables.groupOf(it.name);
			if (g == null || !Consumables.enabled(g, cfg))
			{
				continue;
			}
			PriceService.Window h = prices.hour.get(it.id);
			if (h == null || h.high <= 0 || h.low <= 0 || h.highVol < 5 || h.lowVol < 5)
			{
				continue;
			}

			long buy = h.low;
			long sell = h.high;
			// Use the most cautious sell price we know: a brief spike in the hour average shouldn't make a margin
			PriceService.Window f5 = prices.fiveMin.get(it.id);
			if (f5 != null && f5.high > 0)
			{
				sell = Math.min(sell, f5.high);
			}
			PriceService.Window d0 = prices.day.get(it.id);
			if (d0 != null && d0.high > 0)
			{
				sell = Math.min(sell, d0.high);
			}
			if (buy < 10)
			{
				continue; // 1 gp margins under 10 gp sit in a huge queue and rarely fill in practice
			}
			long margin = sell - Gp.taxPerItem(sell) - buy;
			long minMargin = Math.max(1, Math.round(buy * 0.005));
			if (margin < minMargin || margin > buy * 0.6)
			{
				continue; // no room after tax, or a margin so wide it's probably one odd trade
			}

			// Spike / slide check against the day, ignoring 1-2 gp wobble on cheap items
			PriceService.Window d = prices.day.get(it.id);
			if (d != null && d.low > 0 && d.high > 0)
			{
				boolean cheap = buy < 200;
				long dl = Math.abs(buy - d.low), dh = Math.abs(sell - d.high);
				if ((!cheap && (dl > d.low * 0.06 || dh > d.high * 0.06)) || (cheap && (dl > 3 && dl > d.low * 0.08)))
				{
					continue;
				}
			}

			// Latest 5 minutes: buyers must still be above break-even
			long be = breakEven(buy);
			PriceService.Window f = prices.fiveMin.get(it.id);
			if (f != null && f.high > 0 && f.high < be)
			{
				continue;
			}

			long limitLeft = it.limit - boughtRecently.applyAsLong(it.id);
			if (limitLeft <= 0)
			{
				continue; // buy limit used up for this 4-hour window
			}
			long vol = Math.min(h.highVol, h.lowVol);
			long qty = Math.min(limitLeft, (long) (vol * (minutes / 60.0) * 0.5));
			qty = Math.min(qty, perSlot / buy);
			if (qty < 1)
			{
				continue;
			}
			long profit = margin * qty;
			if (profit < minProfit)
			{
				continue;
			}

			Suggestion s = new Suggestion();
			s.id = it.id;
			s.name = it.name;
			s.buy = buy;
			s.sell = sell;
			s.qty = qty;
			s.profit = profit;
			s.cost = qty * buy;
			s.breakEven = be;
			s.perHour = vol;
			s.fillMinutes = (int) Math.max(1, Math.round(qty * 60.0 / Math.max(1, vol)));
			candidates.add(s);
		}

		candidates.sort(Comparator.comparingLong((Suggestion s) -> s.profit).reversed());

		// Week trend only for the top few, cached for hours
		int checked = 0;
		for (Suggestion s : candidates)
		{
			if (out.size() >= SHOWN)
			{
				break;
			}
			if (checked < TREND_CANDIDATES)
			{
				checked++;
				PriceService.Trend t = prices.trend(s.id, onTrend);
				if (t == null)
				{
					s.status = "checking";
					s.why = "Loading the week chart";
				}
				else
				{
					String[] c = classify(t.mids);
					s.status = c[0];
					s.why = c[1];
				}
			}
			else
			{
				s.status = "unchecked";
				s.why = "Week chart not checked (keeps Wiki requests low)";
			}
			boolean risky = "sliding".equals(s.status) || "spiking".equals(s.status) || "swingy".equals(s.status);
			if (risky && !cfg.showRisky())
			{
				continue;
			}
			out.add(s);
		}

		// Fit the list inside the total budget, best first
		long left = budget;
		List<Suggestion> fitted = new ArrayList<>();
		for (Suggestion s : out)
		{
			if (s.cost <= left)
			{
				fitted.add(s);
				left -= s.cost;
			}
		}
		return fitted;
	}

	/** Same week-chart rules as Steady Flips. Returns {status, reason}. */
	static String[] classify(List<Long> p)
	{
		if (p.size() < 16)
		{
			return new String[]{"unchecked", "Not enough history"};
		}
		double mean = p.stream().mapToLong(Long::longValue).average().orElse(0);
		double sd = Math.sqrt(p.stream().mapToDouble(x -> (x - mean) * (x - mean)).sum() / p.size());
		double last = p.get(p.size() - 1);
		double week = last / p.get(0) - 1, dev = last / mean - 1, cv = sd / mean;
		List<Long> l6 = p.subList(p.size() - 6, p.size());
		double lmean = l6.stream().mapToLong(Long::longValue).average().orElse(1);
		double rng = (l6.stream().mapToLong(Long::longValue).max().orElse(0) - l6.stream().mapToLong(Long::longValue).min().orElse(0)) / lmean;
		double tr = last / l6.get(0) - 1;
		boolean cheap = mean < 200;
		double wLim = mean >= 5e6 ? 0.08 : 0.12;
		String why = String.format("Week %+.1f%%, last 36h %+.1f%%", week * 100, tr * 100);
		if (cheap && (p.stream().mapToLong(Long::longValue).max().orElse(0) - p.stream().mapToLong(Long::longValue).min().orElse(0)) <= 2)
		{
			return new String[]{"steady", "Within 2 gp all week"};
		}
		if (week < -wLim && Math.abs(tr) < 0.03 && rng < 0.05 && dev < 0.04)
		{
			return new String[]{"settled", "Fell earlier (week " + String.format("%+.1f%%", week * 100) + ") but flat for 36h: sell promptly"};
		}
		if (week < -wLim || tr < -0.05)
		{
			return new String[]{"sliding", why};
		}
		if (dev > 0.06 || tr > 0.05)
		{
			return new String[]{"spiking", why};
		}
		if (Math.abs(week) >= wLim || cv >= 0.08 || rng >= 0.07 || Math.abs(dev) >= 0.06)
		{
			return new String[]{"swingy", why};
		}
		return new String[]{"steady", why};
	}

	static long breakEven(long cost)
	{
		long s = Math.max(0, (long) Math.ceil(cost / 0.98) - 2);
		while (s - Gp.taxPerItem(s) < cost)
		{
			s++;
		}
		return s;
	}

	static long parse(String s, long dflt)
	{
		if (s == null)
		{
			return dflt;
		}
		String t = s.trim().toLowerCase().replace(",", "").replace(" ", "");
		if (t.isEmpty())
		{
			return dflt;
		}
		double mult = 1;
		char last = t.charAt(t.length() - 1);
		if (last == 'k' || last == 'm' || last == 'b')
		{
			mult = last == 'k' ? 1e3 : last == 'm' ? 1e6 : 1e9;
			t = t.substring(0, t.length() - 1);
		}
		try
		{
			return Math.round(Double.parseDouble(t) * mult);
		}
		catch (NumberFormatException e)
		{
			return dflt;
		}
	}
}

package com.flipledger;

import java.awt.Dimension;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;

/**
 * A panel that always matches the sidebar's width inside a scroll pane, so text wraps
 * or shortens instead of running off the right edge.
 */
class WidthPanel extends JPanel implements Scrollable
{
	WidthPanel(LayoutManager layout)
	{
		super(layout);
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
	{
		return visible.height;
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}
}

